type ExecuteFn = (
	toolCallId: string,
	params: unknown,
	signal?: unknown,
	onUpdate?: unknown,
	ctx?: unknown,
) => Promise<any>;

function makeStubApi(): { api: any; getExecute: () => ExecuteFn; getConfig: () => any } {
	let captured: ExecuteFn | null = null;
	let capturedConfig: any;
	const api = {
		registerTool(config: any) {
			if (config?.name === "read_session" && typeof config?.execute === "function") {
				captured = config.execute.bind(config);
				capturedConfig = config;
			}
		},
	};
	return {
		api,
		getExecute: () => {
			if (!captured) throw new Error("read_session execute was not registered");
			return captured;
		},
		getConfig: () => {
			if (!capturedConfig) throw new Error("read_session config was not registered");
			return capturedConfig;
		},
	};
}

function parseToolError(result: any): { error: string; code: string } {
	assert.equal(result.isError, true);
	assert.equal(result.details, undefined);
	assert.equal(result.content?.length, 1);
	return JSON.parse(result.content[0].text);
}

describe("shared context-heavy guard", () => {
	it("centralizes the cap and deterministic per-tool flag classification", () => {
		assert.equal(CONTEXT_HEAVY_LIMIT, 10);
		assert.equal(CONTEXT_HEAVY_ERROR_CODE, "CONTEXT_HEAVY_LIMIT_REQUIRED");
		assert.deepEqual(CONTEXT_HEAVY_FLAGS, {
			bobbit_read: ["verbose"],
			bobbit_orchestrate: ["verbose"],
			bobbit_admin: ["verbose"],
			read_session: ["verbose", "include_tool_results"],
		});
		assert.deepEqual(
			activeContextHeavyFlags("read_session", {
				include_tool_results: true,
				verbose: true,
			}),
			["verbose", "include_tool_results"],
		);
	});

	it("activates flags only for boolean true and skips non-pageable operations", () => {
		assert.deepEqual(activeContextHeavyFlags("bobbit_read", { verbose: "true" }), []);
		assert.deepEqual(activeContextHeavyFlags("bobbit_read", { verbose: 1 }), []);
		assert.deepEqual(activeContextHeavyFlags("bobbit_read", { verbose: false }), []);
		assert.equal(contextHeavyLimitError("bobbit_admin", { verbose: true }, false), undefined);
	});

	it.each([undefined, 0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, 11, "10"])(
		"rejects an unsafe raw explicit limit (%s)",
		(limit) => {
			const error = contextHeavyLimitError("read_session", { verbose: true, limit }, true);
			assert.equal(error?.code, CONTEXT_HEAVY_ERROR_CODE);
			assert.equal(error?.error, formatContextHeavyLimitGuidance(["verbose"]));
		},
	);

	it.each([1, CONTEXT_HEAVY_LIMIT])("accepts an explicit integer limit of %s", (limit) => {
		assert.equal(
			contextHeavyLimitError("read_session", { include_tool_results: true, limit }, true),
			undefined,
		);
	});

	it("formats every active flag and all canonical recovery guidance", () => {
		const message = formatContextHeavyLimitGuidance(["verbose", "include_tool_results"]);
		assert.equal(
			message,
			"You should not typically pull this much data from the API. " +
				"Context-heavy flag(s) `verbose`, `include_tool_results` require an explicit limit at or below 10. " +
				"Call again with limit <= 10 and fetch in smaller batches only if you REALLY need full verbosity. " +
				"Keep an eye on token consumption.",
		);
		assert.match(CONTEXT_HEAVY_LIMIT_GUIDANCE, /\{flags\}/);
		assert.equal((CONTEXT_HEAVY_LIMIT_GUIDANCE.match(/\{cap\}/g) ?? []).length, 2);
	});
});

describe("read_session extension context-heavy guard", () => {
	let execute: ExecuteFn;
	let toolConfig: any;
	const envBackup: Record<string, string | undefined> = {};
	let realFetch: typeof globalThis.fetch;
	let responseOk = true;
	let responseStatus = 200;
	let responseBody: any;
	const seenUrls: string[] = [];

	beforeAll(() => {
		for (const key of ["BOBBIT_SESSION_ID", "BOBBIT_TOKEN", "BOBBIT_GATEWAY_URL"]) {
			envBackup[key] = process.env[key];
		}
		process.env.BOBBIT_SESSION_ID = "caller-session";
		process.env.BOBBIT_TOKEN = "test-token";
		process.env.BOBBIT_GATEWAY_URL = "https://gateway.test";

		realFetch = globalThis.fetch;
		globalThis.fetch = (async (url: any) => {
			seenUrls.push(String(url));
			return {
				ok: responseOk,
				status: responseStatus,
				async json() {
					return responseBody;
				},
			} as any;
		}) as any;

		const { api, getExecute, getConfig } = makeStubApi();
		registerAgentExtension(api);
		execute = getExecute();
		toolConfig = getConfig();
	});

	beforeEach(() => {
		seenUrls.length = 0;
		responseOk = true;
		responseStatus = 200;
		responseBody = { total: 1, returned: 0, offsetStart: -1, offsetEnd: -1, messages: [] };
	});

	afterAll(() => {
		globalThis.fetch = realFetch;
		for (const key of ["BOBBIT_SESSION_ID", "BOBBIT_TOKEN", "BOBBIT_GATEWAY_URL"]) {
			if (envBackup[key] === undefined) delete process.env[key];
			else process.env[key] = envBackup[key]!;
		}
	});

	it("keeps ordinary reads at their existing defaults", async () => {
		const result = await execute("toolu_READ", { session_id: "target-session" });
		assert.notEqual(result.isError, true);
		assert.equal(seenUrls.length, 1);
		const url = new URL(seenUrls[0]);
		assert.equal(url.pathname, "/api/sessions/target-session/transcript");
		assert.equal(url.searchParams.has("limit"), false);
		assert.equal(url.searchParams.has("verbose"), false);
		assert.equal(url.searchParams.get("include_tool_results"), "0");
		assert.equal(url.searchParams.has("result_handle"), false);
		assert.equal(url.searchParams.has("result_cursor"), false);
		assert.equal(url.searchParams.has("result_limit"), false);
	});

	it("registers result-slice parameters and compact-first guidance", () => {
		assert.deepEqual(
			Object.keys(toolConfig.parameters.properties).filter((key) => key.startsWith("result_")),
			["result_handle", "result_cursor", "result_limit"],
		);
		const guidance = toolConfig.promptGuidelines.join(" ");
		assert.match(guidance, /small compact tail or regex page/i);
		assert.match(guidance, /result_handle/);
		assert.match(guidance, /nextCursor/);
		assert.match(guidance, /without overlapping/i);
		assert.match(guidance, /stop as soon as/i);
	});

	it("forwards a targeted result handle, zero cursor, and bounded slice limit", async () => {
		const result = await execute("toolu_READ", {
			session_id: "target-session",
			result_handle: "rs1:m6h:b0:NUBAzC7icgMYwEPyuR8OFQyx29U",
			result_cursor: 0,
			result_limit: 8192,
		});
		assert.notEqual(result.isError, true);
		assert.equal(seenUrls.length, 1);
		const url = new URL(seenUrls[0]);
		assert.equal(url.searchParams.get("result_handle"), "rs1:m6h:b0:NUBAzC7icgMYwEPyuR8OFQyx29U");
		assert.equal(url.searchParams.get("result_cursor"), "0");
		assert.equal(url.searchParams.get("result_limit"), "8192");
	});

	it("returns canonical partial envelopes once and keeps details scalar-only", async () => {
		const messages = [{
			index: 7,
			role: "assistant",
			toolResults: [{ name: "bash", status: "ok", omitted: true }],
		}];
		responseBody = {
			total: 12,
			matchCount: 3,
			returned: 1,
			offsetStart: 7,
			offsetEnd: 7,
			nextOffset: 2,
			messages,
			partial: true,
			truncatedBy: "transport_budget",
			continuationRequest: { kind: "page", offset: 2 },
			authors: { a1: { kind: "agent", label: "Reviewer" } },
			correlations: { t1: { name: "bash", messageIndex: 7, blockIndex: 0 } },
		};
		const sessionId = `${"x".repeat(63)}😀suffix`;

		const result = await execute("toolu_READ", { session_id: sessionId });

		assert.deepEqual(JSON.parse(result.content[0].text), responseBody);
		assert.deepEqual(result.details, {
			session_id: "x".repeat(63),
			sessionIdTruncated: true,
			total: 12,
			matchCount: 3,
			returned: 1,
			offsetStart: 7,
			offsetEnd: 7,
			nextOffset: 2,
		});
		assert.equal("messages" in result.details, false);
		assert.equal("authors" in result.details, false);
		assert.equal("correlations" in result.details, false);
		assert.equal(JSON.stringify(result.details).includes("toolResults"), false);
	});

	it("refits a completed negative context tail from its resolved expanded position", async () => {
		const escapedText = "\\\"\n".repeat(4_096).slice(0, 4_096);
		const argumentPreview = escapedText.slice(0, 512);
		responseBody = {
			total: 10,
			matchCount: 2,
			pageStart: 4,
			pageCount: 6,
			returned: 2,
			offsetStart: 8,
			offsetEnd: 9,
			messages: [8, 9].map((index) => ({
				index,
				role: "assistant",
				text: escapedText,
				toolCalls: Array.from({ length: 12 }, (_, callIndex) => ({
					ref: `t${index}-${callIndex}`,
					name: "bash",
					argumentsPreview: argumentPreview,
					argumentsTruncated: true,
				})),
			})),
		};

		const result = await execute("toolu_READ", {
			session_id: "target-session",
			pattern: "needle",
			context: 1,
			offset: -2,
			limit: 2,
			verbose: true,
		});

		assert.ok(Buffer.byteLength(JSON.stringify(result), "utf8") <= 50 * 1024);
		const projected = JSON.parse(result.content[0].text);
		assert.equal(projected.partial, true);
		assert.equal(projected.truncatedBy, "transport_budget");
		assert.equal(projected.pageStart, 4);
		assert.equal(projected.pageCount, 6);
		assert.equal(projected.returned, 1);
		assert.deepEqual(projected.messages.map((message: any) => message.index), [8]);
		assert.equal(projected.nextOffset, 5);
		assert.deepEqual(projected.continuationRequest, { kind: "page", offset: 5 });
	});

	it("preserves structured gateway errors for result slices", async () => {
		responseOk = false;
		responseStatus = 400;
		responseBody = { error: "INVALID_RESULT_CURSOR", detail: "cursor splits a Unicode scalar" };

		const result = await execute("toolu_READ", {
			session_id: "target-session",
			result_handle: "rs1:m0:b0:invalid",
			result_cursor: 2,
		});

		assert.deepEqual(parseToolError(result), responseBody);
		assert.equal(seenUrls.length, 1);
	});

	it.each([
		["verbose", { verbose: true }],
		["include_tool_results", { include_tool_results: true }],
	] as const)("rejects %s without an explicit limit before fetching", async (flag, heavyParams) => {
		const result = await execute("toolu_READ", {
			session_id: "target-session",
			...heavyParams,
		});
		const error = parseToolError(result);
		assert.equal(seenUrls.length, 0);
		assert.equal(error.code, CONTEXT_HEAVY_ERROR_CODE);
		assert.equal(error.error, formatContextHeavyLimitGuidance([flag]));
		assert.match(error.error, /should not typically pull this much data/i);
		assert.match(error.error, /fetch in smaller batches/i);
		assert.match(error.error, /REALLY need full verbosity/);
		assert.match(error.error, /token consumption/i);
	});

	it.each([
		["verbose", { verbose: true }],
		["include_tool_results", { include_tool_results: true }],
	] as const)("rejects %s above the conservative cap before fetching", async (flag, heavyParams) => {
		const result = await execute("toolu_READ", {
			session_id: "target-session",
			limit: CONTEXT_HEAVY_LIMIT + 1,
			...heavyParams,
		});
		const error = parseToolError(result);
		assert.equal(seenUrls.length, 0);
		assert.equal(error.code, CONTEXT_HEAVY_ERROR_CODE);
		assert.equal(error.error, formatContextHeavyLimitGuidance([flag]));
	});

	it.each([0, -1, 1.5, Number.NaN, Number.POSITIVE_INFINITY, "10"])(
		"rejects non-integer or non-number heavy limit %s before fetching",
		async (limit) => {
			const result = await execute("toolu_READ", {
				session_id: "target-session",
				limit,
				verbose: true,
			});
			const error = parseToolError(result);
			assert.equal(seenUrls.length, 0);
			assert.equal(error.code, CONTEXT_HEAVY_ERROR_CODE);
			assert.equal(error.error, formatContextHeavyLimitGuidance(["verbose"]));
		},
	);

	it("names both active flags in canonical order", async () => {
		const result = await execute("toolu_READ", {
			session_id: "target-session",
			include_tool_results: true,
			verbose: true,
		});
		const error = parseToolError(result);
		assert.equal(seenUrls.length, 0);
		assert.equal(
			error.error,
			formatContextHeavyLimitGuidance(["verbose", "include_tool_results"]),
		);
	});

	it.each([
		["verbose", { verbose: true }, "1", "0"],
		["include_tool_results", { include_tool_results: true }, null, "1"],
		["both heavy flags", { verbose: true, include_tool_results: true }, "1", "1"],
	] as const)("allows %s at the cap and forwards it unchanged", async (_flag, heavyParams, verbose, toolResults) => {
		const result = await execute("toolu_READ", {
			session_id: "target-session",
			limit: CONTEXT_HEAVY_LIMIT,
			...heavyParams,
		});
		assert.notEqual(result.isError, true);
		assert.equal(seenUrls.length, 1);
		const url = new URL(seenUrls[0]);
		assert.equal(url.searchParams.get("limit"), String(CONTEXT_HEAVY_LIMIT));
		assert.equal(url.searchParams.get("verbose"), verbose);
		assert.equal(url.searchParams.get("include_tool_results"), toolResults);
	});
});
